#!/usr/bin/env python3
"""Generate static build-time PLURAL rules from pinned MediaWiki XML data.

No network or ambient ICU/CLDR dependency. Conditions become direct Zig
branches; source order is positional, and the MediaWiki file overrides the base.
See tools/data/mediawiki-plurals for original data, notices and provenance.
"""
import argparse
import hashlib
from pathlib import Path
import re
import xml.etree.ElementTree as ET

PINS = {
    'plurals.xml': '01ef1e007ca9014b4c45aed61498a3ce9e014dac5618657776c05aae939adc47',
    'plurals-mediawiki.xml': 'fae28b0f21750f63f342e2247a2bc66f64af97ed33402b560805cb7c1b7f15d8',
}
HEADER = r'''// Generated by tools/generate_plural_rules.py; do not edit rule families.
// MediaWiki 0d3b507d19ae860ed8a1d22c73fa4bc5abf8dfcc languages/data/plurals*.xml.
// Base data: Copyright Unicode, Inc.; MediaWiki overrides: MediaWiki contributors.
// Original notices and component licence texts: tools/data/mediawiki-plurals/.
// Build-time expansion only. No XML parser, dynamic rules, or reader dependency.
const std = @import("std");

const Operands = struct { n: f64, i: f64, v: f64, w: f64, f: f64, t: f64 };

// The caller first applies MediaWiki's int/float count coercion. A normalized
// numeric string therefore has no insignificant trailing decimal zeros.
fn operands(raw: []const u8) ?Operands {
    var text = raw;
    if (text.len != 0 and text[0] == '-') text = text[1..];
    if (text.len == 0) return null;
    // CLDRPluralRuleParser 3.0.2 rejects signed scientific exponents. The
    // deployed PHP number formatter emits signed exponents for large/small
    // floats; those consequently select the final (other) positional rule.
    const end = std.mem.indexOfAny(u8, text, "eEcC") orelse text.len;
    if (end < text.len) {
        if (end + 1 == text.len) return null;
        for (text[end + 1 ..]) |byte| if (!std.ascii.isDigit(byte)) return null;
    }
    text = text[0..end];
    const point = std.mem.indexOfScalar(u8, text, '.') orelse text.len;
    if (point == 0) return null;
    for (text[0..point]) |byte| if (!std.ascii.isDigit(byte)) return null;
    const whole = std.fmt.parseFloat(f64, text[0..point]) catch return null;
    const n = std.fmt.parseFloat(f64, text) catch return null;
    if (!std.math.isFinite(n) or !std.math.isFinite(whole)) return null;
    const fraction = if (point == text.len) "" else text[point + 1 ..];
    if (point != text.len and fraction.len == 0) return null;
    for (fraction) |byte| if (!std.ascii.isDigit(byte)) return null;
    const trimmed = std.mem.trimEnd(u8, fraction, "0");
    return .{ .n = n, .i = whole, .v = @floatFromInt(fraction.len), .w = @floatFromInt(trimmed.len), .f = if (fraction.len == 0) 0 else std.fmt.parseFloat(f64, fraction) catch return null, .t = if (trimmed.len == 0) 0 else std.fmt.parseFloat(f64, trimmed) catch return null };
}

// Empty CLDR families trigger the captured MediaWiki fallback chain.
pub fn hasRules(code: []const u8) bool {
    return (languages.get(code) orelse return false) != 0;
}

pub fn index(code: []const u8, normalized_count: []const u8) ?usize {
    const family = languages.get(code) orelse return null;
    const value = operands(normalized_count);
    return select(family, value);
}

fn select(family: u8, value: ?Operands) usize {
    return switch (family) {
'''

def condition(source):
    disjunction = []
    for term in source.split(' or '):
        conjunction = []
        for atom in term.split(' and '):
            m = re.fullmatch(r'([nivwft])(?: % ([1-9][0-9]*))? (!?=) ([0-9]+(?:\.\.[0-9]+)?(?:,[0-9]+(?:\.\.[0-9]+)?)*)', atom)
            if not m:
                raise ValueError('Unsupported pinned plural condition: '+atom)
            operand, modulo, operator, ranges = m.groups()
            value = 'o.'+operand
            if modulo:
                value = '@mod('+value+', '+modulo+')'
            values = []
            for interval in ranges.split(','):
                ends = interval.split('..')
                if len(ends) == 1:
                    values.append(value+' == '+ends[0])
                else:
                    lo, hi = map(int, ends)
                    if lo > hi: raise ValueError('Reversed plural interval')
                    values.append('('+value+' >= '+str(lo)+' and '+value+' <= '+str(hi)+')')
            # CLDR '=' is integer set membership, not fractional 'within'.
            joined = '(@trunc('+value+') == '+value+' and ('+' or '.join(values)+'))'
            conjunction.append('!'+joined if operator == '!=' else joined)
        disjunction.append('('+' and '.join(conjunction)+')')
    return ' or '.join(disjunction)

def load_rules(data):
    languages = {}
    for name, expected in PINS.items():
        raw = (data/name).read_bytes()
        if hashlib.sha256(raw).hexdigest() != expected:
            raise ValueError('Pinned plural source changed: '+name)
        for rules in ET.fromstring(raw).findall('.//pluralRules'):
            forms=[]
            for rule in rules:
                expression=(rule.text or '').split('@',1)[0].strip()
                if rule.attrib['count']=='other':
                    if expression:raise ValueError('Unexpected other condition')
                else:
                    condition(expression)
                    forms.append((rule.attrib['count'], expression))
            for code in rules.attrib['locales'].split():
                if not re.fullmatch('[A-Za-z0-9_-]+',code):raise ValueError('Invalid language code')
                languages[code]=tuple(forms)
    return languages

def generate(data):
    languages=load_rules(data)
    families=sorted(set(languages.values()))
    assert families[0] == (), "Empty family must retain number zero"
    out=[HEADER]
    for number, rules in enumerate(families):
        out.append('        '+str(number)+' => blk: { // '+', '.join(x[0] for x in rules)+', other\n')
        if rules:
            out.append('            const o = value orelse break :blk '+str(len(rules))+';\n')
            for i, (_, expression) in enumerate(rules):
                out.append('            if ('+condition(expression)+') break :blk '+str(i)+';\n')
        out.append('            break :blk '+str(len(rules))+';\n        },\n')
    out.append('        else => unreachable,\n    };\n}\n\nconst languages = std.StaticStringMap(u8).initComptime(.{\n')
    for code,rules in sorted(languages.items()):out.append('    .{ "'+code+'", '+str(families.index(rules))+' },\n')
    out.append('});\n')
    out.append('\ntest "pinned plural families select Arabic and Slavic positional categories" {\n    const Case = struct { code: []const u8, count: []const u8, expected: usize };\n    const cases = [_]Case{\n        .{ .code = "ar", .count = "0", .expected = 0 },\n        .{ .code = "ar", .count = "1", .expected = 1 },\n        .{ .code = "ar", .count = "2", .expected = 2 },\n        .{ .code = "ar", .count = "3", .expected = 3 },\n        .{ .code = "ar", .count = "11", .expected = 4 },\n        .{ .code = "ar", .count = "100", .expected = 5 },\n        .{ .code = "ar", .count = "3.5", .expected = 5 },\n        .{ .code = "ru", .count = "1", .expected = 0 },\n        .{ .code = "ru", .count = "2", .expected = 1 },\n        .{ .code = "ru", .count = "5", .expected = 2 },\n        .{ .code = "ru", .count = "11", .expected = 2 },\n        .{ .code = "ru", .count = "21", .expected = 0 },\n        .{ .code = "ru", .count = "22", .expected = 1 },\n        .{ .code = "ru", .count = "1.5", .expected = 3 },\n        .{ .code = "pl", .count = "1", .expected = 0 },\n        .{ .code = "pl", .count = "2", .expected = 1 },\n        .{ .code = "pl", .count = "12", .expected = 2 },\n        .{ .code = "pl", .count = "22", .expected = 1 },\n    };\n    for (cases) |case| try std.testing.expectEqual(case.expected, index(case.code, case.count).?);\n}\n\ntest "plural operands preserve fraction relations and MediaWiki overrides" {\n    try std.testing.expectEqual(@as(usize, 0), index("en", "1").?);\n    try std.testing.expectEqual(@as(usize, 0), index("en", "-1").?);\n    try std.testing.expectEqual(@as(usize, 1), index("en", "1.5").?);\n    try std.testing.expectEqual(@as(usize, 1), index("en", "1e+20").?);\n    try std.testing.expectEqual(@as(usize, 1), index("en", "invalid").?);\n    // XML \'=\' denotes integer set membership: Arabic 3.5 is not in 3..10.\n    try std.testing.expectEqual(@as(usize, 5), index("ar", "3.5").?);\n    // The pinned French family selects the first form when i is 0 or 1.\n    try std.testing.expectEqual(@as(usize, 0), index("fr", "1.5").?);\n    try std.testing.expectEqual(@as(usize, 1), index("fr", "2").?);\n    const o = operands("-12.340").?;\n    try std.testing.expectEqual(@as(f64, 12.34), o.n);\n    try std.testing.expectEqual(@as(f64, 12), o.i);\n    try std.testing.expectEqual(@as(f64, 3), o.v);\n    try std.testing.expectEqual(@as(f64, 2), o.w);\n    try std.testing.expectEqual(@as(f64, 340), o.f);\n    try std.testing.expectEqual(@as(f64, 34), o.t);\n    try std.testing.expect(operands("1e-7") == null);\n}\n\ntest "empty and absent families require explicit language fallback" {\n    try std.testing.expect(hasRules("en"));\n    try std.testing.expect(hasRules("ar"));\n    try std.testing.expect(!hasRules("ja"));\n    try std.testing.expect(!hasRules("aa"));\n    try std.testing.expect(!hasRules("unknown-language"));\n    try std.testing.expect(index("unknown-language", "2") == null);\n    // Literal upstream keys are retained; no language-tag truncation or alias.\n    try std.testing.expect(hasRules("pt_PT"));\n    try std.testing.expect(!hasRules("pt-PT"));\n}\n')
    return ''.join(out)

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--data',type=Path,default=Path(__file__).resolve().parent/'data/mediawiki-plurals')
    p.add_argument('--output',type=Path,default=Path(__file__).resolve().parents[1]/'src/lua/runtime/plural_rules.zig')
    p.add_argument('--check',action='store_true')
    a=p.parse_args();value=generate(a.data)
    if a.check:
        if a.output.read_text()!=value:raise SystemExit('Generated plural rules differ')
    else:a.output.write_text(value)

if __name__=='__main__':main()
